const HEAD = 0;

/**
 * Fixed-capacity least-recently-used cache.
 *
 * A Map indexes keys to slots; slots form a circular doubly linked list
 * (stored in typed arrays) ordered from most to least recently used, with
 * slot 0 as the sentinel. Every operation is O(1) expected time.
 *
 * Map iteration order is deliberately not used for eviction: after many
 * deletions V8 must skip the leading holes on each `keys().next()`, which
 * degrades eviction far beyond O(1).
 */
export class LruCache {
  #capacity;
  #index = new Map();
  #keys;
  #values;
  #prev;
  #next;
  /** Slots that have never been used start at #fresh; freed slots are chained through #next. */
  #fresh = 1;
  #free = HEAD;

  /** @param {number} capacity maximum number of keys held (>= 1) */
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.#capacity = capacity;
    // One spare slot lets SET insert before evicting.
    const slots = capacity + 2;
    this.#keys = new Array(slots).fill(undefined);
    this.#values = new Array(slots).fill(undefined);
    this.#prev = new Int32Array(slots);
    this.#next = new Int32Array(slots);
  }

  get size() {
    return this.#index.size;
  }

  /** @returns {string | undefined} */
  get(key) {
    const slot = this.#index.get(key);
    if (slot === undefined) return undefined;
    this.#unlink(slot);
    this.#pushFront(slot);
    return this.#values[slot];
  }

  set(key, value) {
    const index = this.#index;
    let slot = index.get(key);
    if (slot !== undefined) {
      this.#unlink(slot);
    } else {
      slot = this.#allocate();
      this.#keys[slot] = key;
      index.set(key, slot);
    }
    this.#values[slot] = value;
    this.#pushFront(slot);
    if (index.size > this.#capacity) this.#remove(this.#prev[HEAD]);
  }

  /** @returns {boolean} whether the key was present */
  delete(key) {
    const slot = this.#index.get(key);
    if (slot === undefined) return false;
    this.#remove(slot);
    return true;
  }

  #allocate() {
    if (this.#free !== HEAD) {
      const slot = this.#free;
      this.#free = this.#next[slot];
      return slot;
    }
    return this.#fresh++;
  }

  #remove(slot) {
    this.#unlink(slot);
    this.#index.delete(this.#keys[slot]);
    this.#keys[slot] = undefined;
    this.#values[slot] = undefined;
    this.#next[slot] = this.#free;
    this.#free = slot;
  }

  #unlink(slot) {
    const prev = this.#prev;
    const next = this.#next;
    const before = prev[slot];
    const after = next[slot];
    next[before] = after;
    prev[after] = before;
  }

  #pushFront(slot) {
    const prev = this.#prev;
    const next = this.#next;
    const first = next[HEAD];
    prev[slot] = HEAD;
    next[slot] = first;
    prev[first] = slot;
    next[HEAD] = slot;
  }
}

import { readFileSync, writeSync } from 'node:fs';
import { LruCache } from './lru-cache.js';

const OUTPUT_CHUNK = 1 << 16;

/**
 * Runs the command script against an LRU cache and returns the output lines.
 * @param {string} input full program input
 * @returns {string[]}
 */
export function run(input) {
  const lines = input.split('\n');
  const capacity = Number.parseInt(lines[0], 10);
  const cache = new LruCache(capacity);
  const out = [];

  for (let i = 1; i < lines.length; i++) {
    let line = lines[i];
    if (line.endsWith('\r')) line = line.slice(0, -1);
    if (line === '') continue;

    const first = line.indexOf(' ');
    const command = first === -1 ? line : line.slice(0, first);
    switch (command) {
      case 'SET': {
        const second = line.indexOf(' ', first + 1);
        cache.set(line.slice(first + 1, second), line.slice(second + 1));
        break;
      }
      case 'GET':
        out.push(cache.get(line.slice(first + 1)) ?? 'NULL');
        break;
      case 'DEL':
        out.push(cache.delete(line.slice(first + 1)) ? '1' : '0');
        break;
      case 'SIZE':
        out.push(String(cache.size));
        break;
      default:
        throw new Error(`line ${i + 1}: unknown command ${JSON.stringify(command)}`);
    }
  }
  return out;
}

function writeAll(fd, text) {
  const buf = Buffer.from(text, 'latin1');
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(fd, buf, offset);
    } catch (err) {
      if (err.code !== 'EAGAIN') throw err;
    }
  }
}

if (import.meta.main) {
  const out = run(readFileSync(0, 'latin1'));
  for (let i = 0; i < out.length; i += OUTPUT_CHUNK) {
    writeAll(1, out.slice(i, i + OUTPUT_CHUNK).join('\n') + '\n');
  }
}
